<div class="cart-dropdown-heading"><h3>Your cart</h3><span><?=e($cart['count'])?> items</span></div>
<?php if(!$cart['items']): ?><div class="cart-empty"><?=ui_icon('bag',48)?><h3>Room for something delicious.</h3><p>Your cart is empty. Explore food to find your next favorite.</p><a class="pill primary" href="<?=e(url('index.php'))?>">Explore Food →</a></div><?php else: ?><div class="dropdown-cart-items"><?php foreach($cart['items'] as $entry): ?><div class="dropdown-cart-row"><img src="<?=e(image_url($entry['photo_id']))?>" alt=""><div class="cart-row-copy"><a href="<?=e(url('dish.php?id='.$entry['id']))?>"><?=e($entry['name'])?></a><small><?=e($entry['business_name'])?></small><span>Rs <?=number_format($entry['price_paisa']/100,2)?></span><form method="post" action="<?=e(url('cart.php'))?>" data-cart-form class="cart-quantity"><?=csrf()?><input type="hidden" name="action" value="quantity"><input type="hidden" name="id" value="<?=$entry['id']?>"><label><span class="sr-only">Quantity for <?=e($entry['name'])?></span><input type="number" name="quantity" value="<?=$entry['quantity']?>" min="1" max="20" required></label><button type="submit">Update</button></form></div><form method="post" action="<?=e(url('cart.php'))?>" data-cart-form><?=csrf()?><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?=$entry['id']?>"><button class="cart-remove" aria-label="Remove <?=e($entry['name'])?>">×</button></form></div><?php endforeach ?></div><div class="cart-subtotal"><span>Subtotal</span><strong>Rs <?=number_format($cart['total']/100,2)?></strong></div><p class="hint">Choose pickup or delivery at checkout. Delivery charges are shown separately.</p><div class="row-actions"><a class="pill primary checkout-cart-link" href="<?=e(url('checkout.php'))?>">Checkout →</a><a class="pill cart-view-link" href="<?=e(url('cart.php'))?>">View cart</a><form method="post" action="<?=e(url('cart.php'))?>" data-cart-form><?=csrf()?><input type="hidden" name="action" value="clear"><button class="pill">Clear</button></form></div><?php endif ?>
